#!/bin/bash
set -eo pipefail
umask 077
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY_TERRAIN_DEPLOY'
import base64,hashlib,io,json,pathlib,re,shutil,subprocess,sys,zipfile
root=pathlib.Path('/data1/home/sunyiq/china_input_completion_hpc_20261015_001/terrain_unit_provenance_v1')
assert root.parent.resolve(strict=True)==root.parent and not root.exists() and not root.is_symlink()
assert shutil.disk_usage(root.parent).free>=8*1024**3
packed=base64.b64decode('',validate=True)
assert len(packed)==26328 and hashlib.sha256(packed).hexdigest()=='7f4c4fa1174c5a6564b51a8102c275c6f1a2e1e32bfba0bf0fcd9534b029bee2'
table=json.loads('{"UNIT_PROVENANCE_REVIEW.json":{"bytes":3638,"sha256":"7252e2fb3926c9cc961e73c5917e2256107040505f80edad3f6a5bad40a5cccd"},"metadata/worldclim21.html":{"bytes":11765,"sha256":"83fa20643bbd95d4b0673ab90eee569f87d0290fb2a5c3448553c5075a35608d"},"metadata/geodata_elevation.html":{"bytes":8728,"sha256":"e37d31114c51fedd64139318c23141c869ea56798ad23e8cc04088497dc99a04"},"metadata/USGS_WEB_EXCERPT.json":{"bytes":815,"sha256":"52aadda46d71b317b5488b75da9d6e2d7c47a994bfe8e87b165e8471c6d402fd"},"metadata/INDEX.json":{"bytes":1482,"sha256":"b2f9cf8ada8211aebc08ff100d792d3b55713fa8861d18687439f81210153396"},"UNIT_PROVENANCE.json":{"bytes":3084,"sha256":"c53dfc8c91f96038e2f1f9b3288844f9f1b84d6e70c65d8dba6ba8f0bad5ba3c"},"terrain_main/topography_main.py":{"bytes":12711,"sha256":"850bc4be1d8184b69b7905507346058a722d476ad221564b23c9055617566d21"},"terrain_independent/topography_independent.py":{"bytes":17167,"sha256":"28efcf1300b77f6107de9141b4db7386b0a3067b56717e55dfb778db606e4482"},"TERRAIN_TEMPLATE.json":{"bytes":1756,"sha256":"af1bfe46830d813646db5e2cf5ea22b1fed06617c67343d7d25fe6e378ea7fca"},"TERRAIN_INDEPENDENT_TEMPLATE.json":{"bytes":466,"sha256":"c7e0a1c5044822b29e1f06c952a281adc275c7d642bb78365cffed8357092dd2"},"terrain_unit_resume_compute_v1.py":{"bytes":9620,"sha256":"103af0a68fb4d1d7b90b3b1c4b42b8141a0be961fe54db406ecb7737aead608c"},"TERRAIN_RESUME_CONTRACT.json":{"bytes":2179,"sha256":"78dcf402ae95bcbc85a7b88093968d81696a8f2c9c333cdd930ec6cf65667345"},"terrain.sbatch":{"bytes":981,"sha256":"03e8188307750a9b84eefcb1ade9e8bb5d280d60c211d180fba1a0d6521d5fbe"}}')
root.mkdir(mode=0o700)
(root/'logs').mkdir(mode=0o700)
with zipfile.ZipFile(io.BytesIO(packed)) as archive:
 assert archive.namelist()==sorted(table) and len(archive.namelist())==len(set(archive.namelist()))
 assert sum(item.file_size for item in archive.infolist())<=4194304
 for name in archive.namelist():
  parts=pathlib.PurePosixPath(name).parts
  assert 1<=len(parts)<=2 and all(p not in ('','.','..') for p in parts) and not name.startswith('/')
  raw=archive.read(name)
  assert len(raw)==table[name]['bytes'] and hashlib.sha256(raw).hexdigest()==table[name]['sha256']
  target=root/name
  target.parent.mkdir(exist_ok=True)
  with target.open('xb') as stream:stream.write(raw)
print('OWN_TERRAIN_UNIT_PAYLOAD_VERIFIED='+str(len(table)),flush=True)
with (root/'SUBMISSION_STARTED.json').open('x') as stream:json.dump(dict(attempt=1,new_source_gets=0,
 scientific_arrays_on_login=0,model_calls=0,automatic_retries=0),stream)
result=dict(exit_code=None,status='SUBMISSION_UNKNOWN_NO_RETRY',stdout='',stderr='')
try:
 outcome=subprocess.run(['sbatch',str(root/'terrain.sbatch')],capture_output=True,timeout=30)
 result.update(exit_code=outcome.returncode,stdout=outcome.stdout[:65536].decode('utf8','replace'),
               stderr=outcome.stderr[:65536].decode('utf8','replace'),
               stdout_bytes=len(outcome.stdout),stderr_bytes=len(outcome.stderr),
               stdout_sha256=hashlib.sha256(outcome.stdout).hexdigest(),
               stderr_sha256=hashlib.sha256(outcome.stderr).hexdigest())
 assert len(outcome.stdout)<=65536 and len(outcome.stderr)<=65536
 jobs=re.findall(r'^Submitted batch job ([0-9]+)$',result['stdout'],re.M)
 assert outcome.returncode==0 and len(jobs)==1
 with (root/'OWN_RECOVERY_JOB_ID').open('x') as stream:stream.write(jobs[0]+'\n')
 result.update(status='UNIQUE_JOB_SUBMITTED',job_id=jobs[0])
except Exception as error:
 result.update(error_type=type(error).__name__,error=str(error))
 if isinstance(error,subprocess.TimeoutExpired):
  for label in ('stdout','stderr'):
   partial=getattr(error,label,None) or b''
   result[label]=partial[:65536].decode('utf8','replace')
   result[label+'_bytes']=len(partial)
   result[label+'_sha256']=hashlib.sha256(partial).hexdigest()
with (root/'SUBMISSION_RESULT.json').open('x') as stream:json.dump(result,stream,indent=2)
print(result['stdout'],end='')
print(result['stderr'],end='')
if result['status']!='UNIQUE_JOB_SUBMITTED':
 print('OWN_TERRAIN_UNIT_SUBMISSION_UNKNOWN_NO_RETRY')
 sys.exit(1)
print('OWN_RECOVERY_JOB_ID='+result['job_id'])
print('OWN_TERRAIN_UNIT_RESUME_SUBMIT_DONE')
PY_TERRAIN_DEPLOY
